/**
 * CST (class-shape transformation) aerofoil geometry, ported from `tools/solver/geometry.py`.
 *
 * The browser rebuilds geometry on every slider drag, so it needs its own evaluator rather than a
 * round trip. Two implementations of one formula drift unless something pins them together: that
 * something is `__fixtures__/cst.json`, generated by `tools/solver/make_ts_fixtures.py` and
 * asserted in `cst.test.ts` to 1e-9.
 *
 *     z(psi) = C(psi) * S(psi),  C(psi) = psi^0.5 * (1 - psi),  S(psi) = sum A_i B_i,5(psi)
 *
 * Conventions are the dataset's, from `docs/DATASET-SCHEMA.md` section 2: chord 1, leading edge at
 * x = 0, sharp trailing edge at x = 1, upper-surface weights positive, lower-surface weights
 * usually negative.
 */

/** Bernstein weights per surface. Fixed by the dataset schema; changing it is a schema change. */
export const CST_ORDER = 6

/** Class-function exponents for a round nose and a sharp tail. */
const CLASS_N1 = 0.5
const CLASS_N2 = 1.0

/** Binomial coefficients of order CST_ORDER - 1, precomputed. */
const BINOMIAL = ((n: number): number[] => {
  const row = [1]
  for (let i = 1; i <= n; i += 1) {
    row.push((row[i - 1]! * (n - i + 1)) / i)
  }
  return row
})(CST_ORDER - 1)

export type Weights = readonly number[]

export interface Point {
  readonly x: number
  readonly z: number
}

export interface SectionMetrics {
  readonly thicknessMax: number
  readonly thicknessMaxX: number
  readonly camberMax: number
  readonly camberMaxX: number
  readonly leRadius: number
  readonly area: number
}

function assertWeights(weights: Weights): void {
  if (weights.length !== CST_ORDER) {
    throw new RangeError(`Expected ${CST_ORDER} CST weights, got ${weights.length}`)
  }
}

/** Class function `C(psi)`. */
export function classFunction(psi: number): number {
  return Math.pow(psi, CLASS_N1) * Math.pow(1 - psi, CLASS_N2)
}

/** Shape function `S(psi)`: the Bernstein expansion of the weights. */
export function shapeFunction(weights: Weights, psi: number): number {
  assertWeights(weights)
  const n = CST_ORDER - 1
  let total = 0
  for (let i = 0; i < CST_ORDER; i += 1) {
    total += weights[i]! * BINOMIAL[i]! * Math.pow(psi, i) * Math.pow(1 - psi, n - i)
  }
  return total
}

/** Surface ordinate `z(psi)` for one surface. Zero at both edges by construction. */
export function cstSurface(weights: Weights, psi: number): number {
  if (psi <= 0 || psi >= 1) {
    return 0
  }
  return classFunction(psi) * shapeFunction(weights, psi)
}

/**
 * Leading-edge radius over chord.
 *
 * With `N1 = 0.5` the surface behaves as `z ~ A_0 sqrt(psi)` at the nose, and a parabola
 * `z^2 = 2 r x` gives `r = A_0^2 / 2` directly. See ADR-013: this closed form is used rather than
 * a fit to the coordinates, which is biased.
 */
export function leadingEdgeRadius(firstUpperWeight: number): number {
  return 0.5 * firstUpperWeight * firstUpperWeight
}

/** Cosine-clustered chordwise stations, clustered toward both edges. */
export function cosineSpacing(count: number): Float64Array {
  if (count < 2) {
    throw new RangeError(`Need at least two stations, got ${count}`)
  }
  const stations = new Float64Array(count)
  const last = count - 1
  for (let j = 0; j <= last; j += 1) {
    stations[j] = 0.5 * (1 - Math.cos((Math.PI * j) / last))
  }
  return stations
}

/**
 * The closed section loop, ordered trailing edge, upper surface, nose, lower surface, trailing
 * edge, with the first point repeated at the end. Matches `tools/solver/geometry.py` exactly, so
 * the same ordering holds on both sides of the project.
 */
export function sectionLoop(
  upperWeights: Weights,
  lowerWeights: Weights,
  panelCount = 160,
): Point[] {
  assertWeights(upperWeights)
  assertWeights(lowerWeights)
  if (panelCount % 2 !== 0) {
    throw new RangeError(`Panel count must be even, got ${panelCount}`)
  }

  const psi = cosineSpacing(panelCount / 2 + 1)
  const loop: Point[] = []
  for (let j = psi.length - 1; j >= 0; j -= 1) {
    const x = psi[j]!
    loop.push({ x, z: cstSurface(upperWeights, x) })
  }
  for (let j = 1; j < psi.length; j += 1) {
    const x = psi[j]!
    loop.push({ x, z: cstSurface(lowerWeights, x) })
  }
  return loop
}

/**
 * Thickness, camber, leading-edge radius and area, on a fine common chordwise grid.
 *
 * The extrema are refined with a parabola through the three samples around the discrete maximum,
 * so a peak between samples is not reported at a grid point.
 */
export function sectionMetrics(
  upperWeights: Weights,
  lowerWeights: Weights,
  samples = 2001,
): SectionMetrics {
  const x = cosineSpacing(samples)
  const thickness = new Float64Array(samples)
  const camber = new Float64Array(samples)
  for (let i = 0; i < samples; i += 1) {
    const upper = cstSurface(upperWeights, x[i]!)
    const lower = cstSurface(lowerWeights, x[i]!)
    thickness[i] = upper - lower
    camber[i] = 0.5 * (upper + lower)
  }

  let thicknessIndex = 0
  let camberIndex = 0
  for (let i = 1; i < samples; i += 1) {
    if (thickness[i]! > thickness[thicknessIndex]!) thicknessIndex = i
    if (Math.abs(camber[i]!) > Math.abs(camber[camberIndex]!)) camberIndex = i
  }

  const [thicknessMax, thicknessMaxX] = refineExtremum(x, thickness, thicknessIndex)
  const [camberMax, camberMaxX] = refineExtremum(x, camber, camberIndex)

  let area = 0
  for (let i = 1; i < samples; i += 1) {
    area += 0.5 * (thickness[i]! + thickness[i - 1]!) * (x[i]! - x[i - 1]!)
  }

  return {
    thicknessMax,
    thicknessMaxX,
    camberMax,
    camberMaxX,
    leRadius: leadingEdgeRadius(upperWeights[0]!),
    area,
  }
}

/** Vertex of the parabola through three samples around `index`, or the sample itself at an edge. */
function refineExtremum(
  x: Float64Array,
  y: Float64Array,
  index: number,
): readonly [number, number] {
  if (index <= 0 || index >= x.length - 1) {
    return [y[index]!, x[index]!]
  }
  const x0 = x[index - 1]!
  const x1 = x[index]!
  const x2 = x[index + 1]!
  const y0 = y[index - 1]!
  const y1 = y[index]!
  const y2 = y[index + 1]!
  const denominator = (x0 - x1) * (x0 - x2) * (x1 - x2)
  if (denominator === 0) {
    return [y1, x1]
  }

  const a = (x2 * (y1 - y0) + x1 * (y0 - y2) + x0 * (y2 - y1)) / denominator
  const b = (x2 * x2 * (y0 - y1) + x1 * x1 * (y2 - y0) + x0 * x0 * (y1 - y2)) / denominator
  if (a === 0) {
    return [y1, x1]
  }

  const vertex = -b / (2 * a)
  if (vertex < x0 || vertex > x2) {
    return [y1, x1]
  }
  const c =
    (x1 * x2 * (x1 - x2) * y0 + x2 * x0 * (x2 - x0) * y1 + x0 * x1 * (x0 - x1) * y2) / denominator
  return [a * vertex * vertex + b * vertex + c, vertex]
}
